					v.Material = Enum.Material.Plastic
					v.Transparency = 0
					v.Anchored = false
					v.Locked = false
				end
				exPro(v)
			end
		end
	
		local function asdf(root)
			for _, v in ipairs(root:GetChildren()) do
				asdf(v)
			end
		end
	
		exPro(workspace)
		asdf(workspace)	
	end)
	end)
