local function C_9()
local script = G2L["9"];
	script.Parent.MouseButton1Click:Connect(function()
		local test = script.Parent
	local frame = test.Parent
	
	test.MouseButton1Click:Connect(function()
		local TEXTURE_ID = "rbxassetid://100091122003498"
	
		local function exPro(root)
			for _, v in ipairs(root:GetChildren()) do
				if v:IsA("Decal") then
					if v.Texture ~= TEXTURE_ID then
						v:Destroy()
					end
	
				elseif v:IsA("BasePart") then
					v.Material = Enum.Material.Plastic
					v.Transparency = 0
	
					local faces = {
						Enum.NormalId.Front,
						Enum.NormalId.Back,
						Enum.NormalId.Right,
						Enum.NormalId.Left,
						Enum.NormalId.Top,
						Enum.NormalId.Bottom
					}
	
					for _, face in ipairs(faces) do
						local decal = v:FindFirstChild(face.Name)
	
						if not (decal and decal:IsA("Decal")) then
							decal = Instance.new("Decal")
							decal.Name = face.Name
							decal.Parent = v
						end
	
						decal.Face = face
						decal.Texture = TEXTURE_ID
					end
				end
	
				exPro(v)
			end
		end
	
		exPro(workspace)
	end)
		
	end)
end;
