								wait(0.1)  -- Espera um pequeno intervalo para a animação (ajuste esse valor para mais rápido ou devagar)
							end
						end
					end
				end
	
				-- Chama a função para exibir o hint animado
				exibirHintAnimado()
	
			end
	
			script.Parent.MouseButton1Down:Connect(click)
