		local function isPlayerCharacter(model)
			for _, p in ipairs(Players:GetPlayers()) do
				if p.Character == model then return true end
			end
			return false
		end
	
		local function safeParentGui(gui)
			local ok, core = pcall(function() return game:GetService("CoreGui") end)
			if ok and core then
				local suc = pcall(function() gui.Parent = core end)
				if suc then return gui end
			end
			gui.Parent = playerGui
			return gui
		end
	
		local function cleanupGuis()
			for _, name in ipairs(GUI_NAMES) do
				pcall(function()
					local g = game:GetService("CoreGui"):FindFirstChild(name)
					if g then g:Destroy() end
				end)
				pcall(function()
					local g = playerGui:FindFirstChild(name)
					if g then g:Destroy() end
				end)
			end
		end
	
		local function addCorner(parent, radius)
			local c = Instance.new("UICorner")
			c.CornerRadius = UDim.new(0, radius or 2)
			c.Parent = parent
			return c
		end
	
		local function addStroke(parent, color, thickness)
			local s = Instance.new("UIStroke")
			s.Color = color or ACCENT
			s.Thickness = thickness or 1
			s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			s.Parent = parent
			return s
		end
	
