			codeBox.Text = ""
			codeBox.TextSize = 14
			codeBox.TextColor3 = ACCENT
			codeBox.BackgroundColor3 = BG2
			codeBox.BorderSizePixel = 0
			codeBox.Parent = panelFrame
			addCorner(codeBox, 2)
