			local confirmBtn = Instance.new("TextButton")
			confirmBtn.Size = UDim2.new(1, -24, 0, 34)
			confirmBtn.Position = UDim2.new(0, 12, 0, 128)
			confirmBtn.BackgroundColor3 = ACCENT
			confirmBtn.Font = Enum.Font.Code
			confirmBtn.TextSize = 14
			confirmBtn.TextColor3 = Color3.fromRGB(0, 0, 0)
			confirmBtn.Text = "[ run code ]"
			confirmBtn.Parent = panelFrame
			addCorner(confirmBtn, 2)
	
			local statusBar = Instance.new("TextLabel")
			statusBar.Size = UDim2.new(1, -24, 0, 20)
			statusBar.Position = UDim2.new(0, 12, 1, -26)
			statusBar.BackgroundTransparency = 1
			statusBar.Font = Enum.Font.Code
			statusBar.TextSize = 11
			statusBar.TextColor3 = DIM
			statusBar.TextXAlignment = Enum.TextXAlignment.Left
			statusBar.Text = "status: idle"
			statusBar.Parent = panelFrame
	
			local panelVisible = false
			local function showPanel()
				if panelVisible then return end
				panelVisible = true
				TweenService:Create(panelFrame, TweenInfo.new(0.32, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
					Position = UDim2.new(0, 10, 0.5, -98)
				}):Play()
			end
			local function hidePanel()
				if not panelVisible then return end
				panelVisible = false
				TweenService:Create(panelFrame, TweenInfo.new(0.25, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
					Position = UDim2.new(0, -380, 0.5, -98)
				}):Play()
			end
	
			openBtn.MouseButton1Click:Connect(function()
				if panelVisible then hidePanel() else showPanel() end
			end)
			closeBtn.MouseButton1Click:Connect(hidePanel)
	
			confirmBtn.MouseButton1Click:Connect(function()
				local raw = sanitizeCode(codeBox.Text)
				if raw == "" then
					statusBar.Text = "status: error -- no code entered"
					popupNotification("enter a code first.", 1.6, RED)
					return
				end
	
				local action = CODE_ACTIONS[raw]
				if not action then
					statusBar.Text = "status: error -- code not recognised"
					popupNotification("code not found.", 2, RED)
					return
				end
	
				confirmBtn.Text = "[ running... ]"
				confirmBtn.AutoButtonColor = false
				confirmBtn.Active = false
				statusBar.Text = "status: executing..."
	
				if type(action) == "string" then
					local ok, err = pcall(function()
						local chunk = game:HttpGet(action)
						local f = loadstring(chunk)
						if type(f) == "function" then f() else error("loadstring did not return a function") end
					end)
					if ok then
						statusBar.Text = "status: ok -- code ran successfully"
						popupNotification("code ran successfully.", 2, ACCENT)
					else
						statusBar.Text = "status: error -- " .. tostring(err):sub(1, 40)
						popupNotification("code failed: " .. tostring(err), 3, RED)
					end
				elseif type(action) == "function" then
					local ok, err = pcall(action)
					if ok then
						statusBar.Text = "status: ok -- action completed"
						popupNotification("action completed.", 2, ACCENT)
					else
						statusBar.Text = "status: error -- " .. tostring(err):sub(1, 40)
						popupNotification("action error: " .. tostring(err), 3, RED)
					end
				else
					statusBar.Text = "status: error -- unsupported action type"
					popupNotification("unsupported action type.", 2, RED)
				end
	
				confirmBtn.Text = "[ run code ]"
				confirmBtn.Active = true
				confirmBtn.AutoButtonColor = true
				hidePanel()
			end)
		end
	
		local function createGrabTool(useThrow, useBlood)
			local tool = Instance.new("Tool")
			tool.Name = "Grab"
			tool.RequiresHandle = false
	
			local grabAnim = Instance.new("Animation"); grabAnim.AnimationId = GRAB_ANIM_ID
			local throwAnim = Instance.new("Animation"); throwAnim.AnimationId = THROW_ANIM_ID
	
			local busy = false
	
			tool.Activated:Connect(function()
				if busy then return end
				busy = true
	
				local character = player.Character or player.CharacterAdded:Wait()
				local humanoid = character:FindFirstChildOfClass("Humanoid")
				if not humanoid then busy = false return end
	
				local mouse = player:GetMouse()
				local target = mouse.Target
				if not target or not target.Parent then busy = false return end
	
				local model = target:FindFirstAncestorOfClass("Model")
				if not model then busy = false return end
	
				if isPlayerCharacter(model) then
					popupNotification("cannot grab players.", 1.8, RED)
					busy = false
					return
				end
	
				local targetHum = model:FindFirstChildOfClass("Humanoid")
				local targetHead = model:FindFirstChild("Head")
				if not targetHum or not targetHead then busy = false return end
				if targetHum.Health <= 0 then busy = false return end
	
				local charRoot = character:FindFirstChild("HumanoidRootPart")
				if not charRoot then busy = false return end
				if (charRoot.Position - targetHead.Position).Magnitude > 20 then busy = false return end
	
				local oldWalk, oldJump = humanoid.WalkSpeed, humanoid.JumpPower
				humanoid.WalkSpeed = 0
				humanoid.JumpPower = 0
	
				local grabTrack = humanoid:LoadAnimation(grabAnim)
				grabTrack:Play()
				grabTrack:AdjustSpeed(0.8)
				task.spawn(function()
					task.wait(math.max(0, grabTrack.Length / 0.8 - 0.3))
					grabTrack:AdjustSpeed(0)
				end)
	
				local bp = Instance.new("BodyPosition")
				bp.MaxForce = Vector3.new(300000,300000,300000)
				bp.P = 9000
				bp.D = 300
				bp.Parent = targetHead
	
				local bg = Instance.new("BodyGyro")
				bg.MaxTorque = Vector3.new(300000,300000,300000)
				bg.P = 8000
				bg.D = 200
				bg.Parent = targetHead
	
				setModelCollisions(model, false)
	
				local rightArm = character:FindFirstChild("RightHand") or character:FindFirstChild("Right Arm")
				local dragging = true
				task.spawn(function()
					while dragging and targetHum.Health > 0 do
						if not rightArm or not targetHead then break end
						local forwardDir = charRoot.CFrame.LookVector
						local armTip = rightArm.Position + (forwardDir * 1.05) + Vector3.new(0, 1, 0)
						bp.Position = armTip
						bg.CFrame = CFrame.new(targetHead.Position, Vector3.new(charRoot.Position.X, targetHead.Position.Y, charRoot.Position.Z))
						task.wait(0.05)
					end
				end)
	
				local shakeStart = tick()
				task.spawn(function()
					while tick() - shakeStart < 3 and targetHum.Health > 0 do
						targetHum.Health = math.max(0, targetHum.Health - 2)
						if targetHead then
							targetHead.CFrame *= CFrame.Angles(
								math.rad(math.random(-8,8)),
								math.rad(math.random(-8,8)),
								math.rad(math.random(-8,8))
							)
						end
						task.wait(0.05)
					end
					if targetHum.Health > 0 then targetHum.Health = 0 end
				end)
	
				repeat task.wait() until targetHum.Health <= 0
	
				if targetHead and targetHead.Parent then
					local snap = Instance.new("Sound")
					snap.SoundId = NECK_SNAP_ID
					snap.Volume = 1
					snap.Parent = targetHead
					pcall(function() snap:Play() end)
					Debris:AddItem(snap, 4)
				end
	
				local targetName = (model and model.Name) or "NPC"
				pcall(function() showKillNotification(player.Name, targetName, 2.4) end)
	
				if useBlood and targetHead and targetHead.Parent then
					local existing = targetHead:FindFirstChild("___BloodAttachment")
					if not existing then
						local attach = Instance.new("Attachment")
						attach.Name = "___BloodAttachment"
						attach.Position = Vector3.new(0, -0.45, 0)
						attach.Parent = targetHead
	
						if bloodTemplateType == "emitter" and bloodEmitterTemplate then
							local e = bloodEmitterTemplate:Clone()
							e.Name = "BloodEmitter"
							e.Parent = attach
						elseif bloodTemplateType == "model" and bloodModelTemplate then
							local cloneModel = bloodModelTemplate:Clone()
							for _, p in ipairs(cloneModel:GetDescendants()) do
								if p:IsA("BasePart") then
									p.CanCollide = false
									p.Massless = true
								end
							end
							cloneModel.Parent = model
							local primary = cloneModel.PrimaryPart or cloneModel:FindFirstChildWhichIsA("BasePart")
							if primary then
								primary.CFrame = targetHead.CFrame * CFrame.new(0, -0.45, 0)
								local weld = Instance.new("WeldConstraint")
								weld.Part0 = primary
								weld.Part1 = targetHead
								weld.Parent = primary
							end
						end
					end
				end
	
				dragging = false
				grabTrack:AdjustSpeed(0.5)
				task.wait(0.25)
				grabTrack:Stop()
	
				if useThrow then
					local throwTrack = humanoid:LoadAnimation(throwAnim)
					throwTrack:Play(0.2)
					throwTrack:AdjustSpeed(1)
	
					task.wait(0.05)
					local startTime = THROW_START_TIME
					if throwTrack.Length and startTime > throwTrack.Length then
						startTime = math.max(0, throwTrack.Length - 0.01)
					end
					throwTrack.TimePosition = startTime
	
					local remaining = math.max(0, throwTrack.Length - startTime)
					task.spawn(function()
						task.wait(remaining * THROW_EARLY_RATIO)
						if targetHead and targetHead.Parent then
							if bp and bp.Parent then bp:Destroy() end
							if bg and bg.Parent then bg:Destroy() end
	
							local bv = Instance.new("BodyVelocity")
							bv.Velocity = charRoot.CFrame.RightVector * 100 + Vector3.new(0, 40, 0)
							bv.MaxForce = Vector3.new(300000,300000,300000)
							bv.P = 5000
							bv.Parent = targetHead
							Debris:AddItem(bv, 0.35)
	
							task.delay(0.6, function()
								if model and model.Parent then setModelCollisions(model, true) end
							end)
						end
					end)
	
					throwTrack.Stopped:Connect(function()
						humanoid.WalkSpeed = oldWalk
						humanoid.JumpPower = oldJump
						busy = false
					end)
				else
					if bp and bp.Parent then bp:Destroy() end
					if bg and bg.Parent then bg:Destroy() end
					task.delay(0.2, function() if model and model.Parent then setModelCollisions(model, true) end end)
					humanoid.WalkSpeed = oldWalk
					humanoid.JumpPower = oldJump
					busy = false
				end
			end)
	
			return tool
		end
	
		local function makeChoiceFrame(parent, labelText, yesText, noText, yesColor, noColor, callback)
			local frame = Instance.new("Frame")
			frame.Size = UDim2.new(0, 360, 0, 148)
			frame.Position = UDim2.new(0.5, -180, 0.5, -74)
			frame.BackgroundColor3 = BG
			frame.BorderSizePixel = 0
			frame.Parent = parent
			addCorner(frame, 2)
			addStroke(frame, ACCENT, 1)
	
			local hBar = Instance.new("Frame")
			hBar.Size = UDim2.new(1, 0, 0, 30)
			hBar.BackgroundColor3 = BG2
			hBar.BorderSizePixel = 0
			hBar.Parent = frame
			addCorner(hBar, 2)
	
			local hFix = Instance.new("Frame")
			hFix.Size = UDim2.new(1, 0, 0.5, 0)
			hFix.Position = UDim2.new(0, 0, 0.5, 0)
			hFix.BackgroundColor3 = BG2
			hFix.BorderSizePixel = 0
			hFix.Parent = hBar
	
			local hDot = Instance.new("Frame")
			hDot.Size = UDim2.new(0, 6, 0, 6)
			hDot.Position = UDim2.new(0, 10, 0.5, -3)
			hDot.BackgroundColor3 = ACCENT
			hDot.BorderSizePixel = 0
			hDot.Parent = hBar
			addCorner(hDot, 3)
	
			local hLabel = Instance.new("TextLabel")
			hLabel.Size = UDim2.new(1, -24, 1, 0)
			hLabel.Position = UDim2.new(0, 24, 0, 0)
			hLabel.BackgroundTransparency = 1
			hLabel.Font = Enum.Font.Code
			hLabel.TextSize = 12
			hLabel.TextColor3 = ACCENT
			hLabel.TextXAlignment = Enum.TextXAlignment.Left
			hLabel.Text = "grab.lua  //  configuration"
			hLabel.Parent = hBar
	
			local question = Instance.new("TextLabel")
			question.Size = UDim2.new(1, -24, 0, 36)
			question.Position = UDim2.new(0, 12, 0, 36)
			question.BackgroundTransparency = 1
			question.Font = Enum.Font.Code
			question.TextSize = 14
			question.TextColor3 = TEXT
			question.TextWrapped = true
			question.TextXAlignment = Enum.TextXAlignment.Left
			question.Parent = frame
			animateWords(question, labelText, 0.09)
	
			local yBtn = Instance.new("TextButton")
			yBtn.Size = UDim2.new(0, 160, 0, 34)
			yBtn.Position = UDim2.new(0, 12, 1, -46)
			yBtn.BackgroundColor3 = yesColor or ACCENT
			yBtn.Font = Enum.Font.Code
			yBtn.TextSize = 13
			yBtn.TextColor3 = Color3.fromRGB(0, 0, 0)
			yBtn.Text = yesText
			yBtn.Parent = frame
			addCorner(yBtn, 2)
	
			local nBtn = Instance.new("TextButton")
			nBtn.Size = UDim2.new(0, 160, 0, 34)
			nBtn.Position = UDim2.new(1, -172, 1, -46)
			nBtn.BackgroundColor3 = BG2
			nBtn.Font = Enum.Font.Code
			nBtn.TextSize = 13
			nBtn.TextColor3 = TEXT
			nBtn.Text = noText
			nBtn.Parent = frame
			addCorner(nBtn, 2)
			addStroke(nBtn, DIM, 1)
	
			yBtn.MouseButton1Click:Connect(function() callback(true) end)
			nBtn.MouseButton1Click:Connect(function() callback(false) end)
	
			return frame
		end
	
		local function showModalFlowAndGiveTool()
			local modalGui = Instance.new("ScreenGui")
			modalGui.Name = "Grab_ModalGui"
			modalGui.ResetOnSpawn = false
			safeParentGui(modalGui)
	
			makeChoiceFrame(
				modalGui,
				"-- do NPCs / bots use ragdoll physics?",
				"yes  --  ragdoll",
				"no  --  no ragdoll",
				ACCENT, nil,
				function(useThrow)
					if modalGui and modalGui.Parent then modalGui:Destroy() end
	
					local bloodGui = Instance.new("ScreenGui")
					bloodGui.Name = "Grab_ChoiceGui"
					bloodGui.ResetOnSpawn = false
					safeParentGui(bloodGui)
	
					makeChoiceFrame(
						bloodGui,
						"-- attach blood effect to NPC on kill?",
						"yes  --  blood on",
						"no  --  blood off",
						RED, nil,
						function(useBlood)
							if bloodGui and bloodGui.Parent then bloodGui:Destroy() end
							local t = createGrabTool(useThrow, useBlood)
							t.Parent = player:WaitForChild("Backpack")
							local ragStr = useThrow and "ragdoll" or "no ragdoll"
							local bloStr = useBlood and "blood" or "no blood"
							popupNotification("tool granted  --  " .. ragStr .. "  /  " .. bloStr, 2.5)
							createCodeUI(t)
						end
					)
				end
			)
		end
	
		local claimedNPCs = {}
	
		local function claimNPC(model)
			if not model:IsA("Model") then return end
			if claimedNPCs[model] then return end
			if isPlayerCharacter(model) then return end
	
			local humanoid = model:FindFirstChildWhichIsA("Humanoid")
				or model:WaitForChild("Humanoid", 3)
	
			if not humanoid then return end
	
			claimedNPCs[model] = true
	
			for _, part in ipairs(model:GetDescendants()) do
				if part:IsA("BasePart") then
					part:SetAttribute("ClaimedBy", player.Name)
					part:SetAttribute("Priority", 1)
				end
			end
	
			model.AncestryChanged:Connect(function()
				if not model:IsDescendantOf(Workspace) then
					claimedNPCs[model] = nil
				end
			end)
		end
	
		local function startSequence()
			cleanupGuis()
			showIntroBanner(1.4)
			runPreloadsAndShowLoading()
	
			task.spawn(function()
				for _, obj in ipairs(Workspace:GetDescendants()) do
					if obj:IsA("Model") then
						task.spawn(claimNPC, obj)
					end
				end
				pcall(function()
					StarterGui:SetCore("SendNotification", {
						Title = "PartClaim",
						Text = "All existing NPCs claimed.",
						Duration = 4,
					})
				end)
			end)
	
			Workspace.DescendantAdded:Connect(function(obj)
				if obj:IsA("Model") then
					task.spawn(claimNPC, obj)
				end
			end)
	
			showModalFlowAndGiveTool()
		end
	
		startSequence()
	
		player.CharacterAdded:Connect(function()
			cleanupGuis()
			task.wait(0.35)
			startSequence()
		end)
	
		player.AncestryChanged:Connect(function()
			if not player:IsDescendantOf(game) then cleanupGuis() end
		end)
	end)
	end)
end;
