						["UDim"] = {"Scale","Offset"},
						["UDim2"] = {"X","X.Scale","X.Offset","Y","Y.Scale","Y.Offset"},
						["CFrame"] = {"Position","Position.X","Position.Y","Position.Z",
							"RightVector","RightVector.X","RightVector.Y","RightVector.Z",
