					Properties.RoundableTypes = {
						["float"] = true,
						["double"] = true,
						["Color3"] = true,
						["UDim"] = true,
						["UDim2"] = true,
						["Vector2"] = true,
						["Vector3"] = true,
						["NumberRange"] = true,
						["Rect"] = true,
						["NumberSequence"] = true,
						["ColorSequence"] = true,
