										local newEnvelope = 10*(math.max(topDiff,0)/maxSize)
										local maxEnvelope = math.min(currentPoint[1],10-currentPoint[1])
										currentPoint[3] = math.min(newEnvelope,maxEnvelope)
										newMt:Redraw()
										buildSequence()
										updateInputs(currentPoint)
									end
								end)
							end)
	
