								for i = 2,#colors do
									local nextColor = colors[i]
									local endPos = math.floor((colorLine.AbsoluteSize.X-1) * nextColor[2]) + 1
									nextColor[3].Position = UDim2.new(0,endPos,0,0)
								end		
							end
							newMt.Redraw = redraw
	
							local function loadSequence(self,seq)
								resetSequence = seq
