									local relativeX = mouse.X - colorLine.AbsolutePosition.X
									if relativeX < 0 then relativeX = 0 end
									if relativeX > maxSize then relativeX = maxSize end
	
									local raw = relativeX/maxSize
									local fromColor = nil
									local toColor = nil
