					}
					local info = TweenInfo.new(0.03,Enum.EasingStyle.Linear,Enum.EasingDirection.Out,0,false,0)
					local tween = tweening:Create(hum,info,propertieschanged)
					tween:Play()
				end)
			end
		end
		local function create(special)
