				Pose = pose
				PoseTime = tick()
			end
	
			function OnRunning(Speed)
				if Speed > 0 then
					SetPose("Running")
				else
					SetPose("Standing")
				end
			end
	
			function OnDied()
				SetPose("Dead")
			end
	
